// Room enables WAL by default. Confirm it on any connection:
fun isWalEnabled(connection: SupportSQLiteConnection): Boolean =
    connection.query("PRAGMA journal_mode").use { c ->
        c.moveToFirst()
        c.getString(0) == "wal"
    }

