fun savePhoto(bytes: ByteArray, durable: Boolean) {
    val dir = if (durable) context.filesDir else context.cacheDir
    File(dir, "photo.jpg").writeBytes(bytes)
}

fun sweepCache(now: Long, maxAgeMillis: Long = 7L * 24 * 60 * 60 * 1000) {
    context.cacheDir.listFiles()?.forEach { file ->
        if (now - file.lastModified() > maxAgeMillis) file.delete()
    }
}

// cacheDir: reclaimable by the system, rebuildable content
// filesDir: durable until uninstall, user-ish content
// Both vanish on uninstall; neither is a place for secrets.

class FeedPagingSource(
    private val dao: FeedDao,
) : PagingSource<Int, Post>() {
    override suspend fun load(params: LoadParams<Int>): LoadResult<Int, Post> {
        val key = params.key ?: 0
        val page = dao.postsAfter(key, params.loadSize)
        return LoadResult.Page(
            data = page,
            prevKey = null,
            nextKey = if (page.size < params.loadSize) null else key + page.size,
        )
    }
}

