fun connect(url: String) {
    val request = Request.Builder().url(url).build()
    client.newWebSocket(request, object : WebSocketListener() {
        override fun onOpen(webSocket: WebSocket, response: Response) {
            // Heartbeat: ping every 30s; a missed pong means dead
            heartbeatScope.launch {
                while (isActive) {
                    webSocket.send("ping")
                    delay(30_000)
                }
            }
        }

        override fun onFailure(webSocket: WebSocket, t: Throwable, response: Response?) {
            // Exponential backoff + jitter, then reconnect
            val delayMs = minOf(60_000L, (1_000L shl attempt)) + Random.nextLong(1_000)
            reconnectScope.launch { delay(delayMs); connect(url) }
            attempt++
        }
    })
}

class FcmService : FirebaseMessagingService() {
    override fun onMessageReceived(message: RemoteMessage) {
        // Data messages always land here — foreground or background
        val syncId = message.data["sync_id"] ?: return
        if (message.notification != null) {
            showTrayNotification(message.notification!!)   // system display path
        }
        // Never do heavy work here — hand off to WorkManager
        val request = OneTimeWorkRequestBuilder<SyncWorker>()
            .setInputData(workDataOf("sync_id" to syncId))
            .build()
        WorkManager.getInstance(this).enqueue(request)
    }
}

val syncRequest = PeriodicWorkRequestBuilder<SyncWorker>(15, TimeUnit.MINUTES)
    .setConstraints(
        Constraints.Builder()
            .setRequiredNetworkType(NetworkType.CONNECTED)
            .setRequiresBatteryNotLow(true)
            .build()
    )
    .build()

WorkManager.getInstance(context).enqueueUniquePeriodicWork(
    "sync", ExistingPeriodicWorkPolicy.UPDATE, syncRequest
)

class SyncWorker(ctx, params) : Worker(ctx, params) {
    override fun doWork(): Result {
        val outbox = db.outboxDao().pending()
        for (mutation in outbox) {
            val ok = api.send(
                mutation.operation,
                idempotencyKey = mutation.clientMutationId,   // server dedupes
            )
            if (!ok) return Result.retry()                    // backoff, item state kept
            db.outboxDao().markDone(mutation.id)
        }
        return Result.success()
    }
}
